if (msg.payload > 50) {
    msg.payload = "Alarma mayor a 50";
} else {
    msg = null;
}
return msg;

let temp = Math.floor(Math.random() * 16) + 20;
let hum = Math.floor(Math.random() * 51) + 30;

msg.url = "http://127.0.0.1:1880/monitoreo/" + temp + "/" + hum;

msg.payload = { temp, hum };

return msg;

let temp = Number(msg.req.params.temp);
let hum = Number(msg.req.params.hum);

if (!Number.isFinite(temp) || !Number.isFinite(hum)) {
    msg.statusCode = 400;
    msg.payload = { error: "Valores inválidos" };
    return [null, null, msg];
}

let msgTemp = {
    payload: temp,
    topic: "Temperatura"
};

let msgHum = {
    payload: hum,
    topic: "Humedad"
};

msg.statusCode = 200;
msg.headers = {
    "Content-Type": "application/json"
};
msg.payload = {
    temp: temp,
    hum: hum
};

return [msgTemp, msgHum, msg];

format:
.hero{background:linear-gradient(135deg,#0f766e,#134e4a);color:#fff;border-radius:10px;padding:28px 24px;text-align:center;margin-bottom:16px}
.hero h1{margin:0 0 6px;font-size:26px;border:0}
.hero p{margin:0;opacity:.85;font-size:14px}
.welcome{background:#f0fdfa;border-left:5px solid #0f766e;border-radius:8px;padding:14px 18px;margin-bottom:18px}
.welcome h2{margin:0 0 4px;font-size:18px;border:0}
.welcome p{margin:0}
.lab-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:14px}
.lab-card{display:flex;gap:14px;align-items:flex-start;background:#fff;border:1px solid #e2e8f0;border-radius:10px;padding:14px 16px;box-shadow:0 1px 3px rgba(0,0,0,.06)}
.lab-num{flex:0 0 38px;height:38px;border-radius:50%;background:#0f766e;color:#fff;font-weight:700;display:flex;align-items:center;justify-content:center}
.lab-card h3{margin:0 0 4px;font-size:16px}
.lab-card p{margin:0 0 8px;font-size:13px;color:#475569}
.lab-card a{font-size:13px;font-weight:600;color:#0f766e;text-decoration:none}

