// =====================================================================
// INICIALIZAR: define los parámetros del modelo y el estado de arranque.
// Entrada 1: contenido de b10_persistencia.json (msg.payload = texto).
// Entrada 2: msg.reset = true  -> vuelve al estado inicial (comando REINICIAR).
// Si el archivo no existe (primer arranque) el nodo catch trae aquí el error
// y simplemente se usa el estado por defecto.
// =====================================================================

// Parámetros físicos. Son valores didácticos de referencia, no de una planta real.
const params = {
    deviceId: 'B10-CAMARA-01',  // identificador del dispositivo en cada mensaje
    version: 2,                 // versión del formato del archivo de persistencia
    dtReal_s: 1,                // el simulador avanza una vez por segundo real
    escalaInicial: 10,          // 1 s real = 10 s simulados (se cambia desde el dashboard)
    escalasPermitidas: [1, 5, 10, 30, 60],
    capacidadTermica_kJK: 300,  // C: energía para subir 1 °C el aire y la estructura (sin producto)
    UAparedes_kWK: 0.12,        // conductancia térmica de las paredes
    UApuerta_kWK: 0.25,         // conductancia equivalente con la puerta abierta
    qInterna_kW: 0.30,          // carga interna fija (luces, ventiladores)
    cargaExtraMax_kW: 5,        // carga térmica adicional máxima (montacargas, equipos)
    cajaMasa_kg: 10,            // masa de una caja de producto
    cajaCp_kJkgK: 3.6,          // calor específico del producto (fruta / alimento)
    hCaja_kWK: 0.015,           // facilidad con que una caja entrega calor al aire
    capacidadCajas: 24,         // cajas que caben en la cámara
    cajasIniciales: 12,         // producto ya almacenado al arrancar
    tIngresoDefecto_C: 25,      // temperatura típica del producto que llega del camión
    tIngresoMin_C: -5,          // límites admitidos para la temperatura de ingreso
    tIngresoMax_C: 40,
    qNominal_kW: 5.0,           // capacidad frigorífica nominal del compresor
    tauCompresor_s: 60,         // constante de tiempo de arranque/parada del compresor
    COP: 2.5,                   // kW de frío producidos por kW eléctrico
    tMinApagado_s: 120,         // protección anti ciclado corto del compresor
    tExtBase_C: 30,             // temperatura exterior media
    tExtAmplitud_C: 3,          // oscilación diaria de la temperatura exterior
    hEntrada_pct: 95,           // humedad a la que tiende el aire que entra
    hEvaporador_pct: 75,        // humedad a la que tiende el aire tras el evaporador
    kHumPuerta_s: 0.004,        // velocidad de humidificación con la puerta abierta
    kHumParedes_s: 0.0001,      // velocidad de humidificación por infiltración normal
    kHumEvaporador_s: 0.0004,   // velocidad de deshumidificación del evaporador
    tMin_C: 2,                  // límite inferior del rango aceptable
    tMax_C: 6,                  // límite superior del rango aceptable
    consignaMin_C: 2,           // consigna mínima admitida por la API
    consignaMax_C: 6,           // consigna máxima admitida por la API
    alarmaRangoRetardo_s: 60,   // tiempo fuera de rango antes de alarmar
    alarmaPuertaRetardo_s: 180, // tiempo de puerta abierta antes de alarmar
    alarmaFallaRetardo_s: 180,  // tiempo pidiendo frío sin obtenerlo antes de alarmar
    qMinimoDetectable_kW: 0.5,  // por debajo de esto se considera que no hay frío
    historialMax: 1440,         // máximo de puntos guardados (12 h simuladas)
    registrosMax: 200           // máximo de alarmas / solicitudes guardadas
};

// Estado físico y lógico que evoluciona con el tiempo.
function estadoInicial() {
    return {
        tSim_s: 0,             // reloj simulado
        tInt: 4.0,             // temperatura interior (°C)
        tExt: 30.0,            // temperatura exterior (°C)
        hum: 80.0,             // humedad relativa (%)
        qFrig: 0.0,            // potencia frigorífica real (kW)
        pElec: 0.0,            // potencia eléctrica (kW)
        ruidoExt: 0.0,         // perturbación lenta de la temperatura exterior
        refrigHabilitada: true,// el operador activó la refrigeración
        demandaFrio: false,    // la histéresis pide frío
        compresorOn: false,    // el compresor está girando
        puertaAbierta: false,  // puerta simulada
        tPuerta_s: 0,          // tiempo acumulado con la puerta abierta
        fallaCompresor: false, // falla inyectada
        cargaExtra_kW: 0,      // carga térmica adicional fijada por el operador
        cajas: params.cajasIniciales, // cajas de producto dentro de la cámara
        tProd: 4.0,            // temperatura media del producto (°C)
        cajasEntrando: 0,      // cajas del último ingreso (para la animación)
        escala: params.escalaInicial, // segundos simulados por segundo real
        consigna: 4.0,         // consigna de temperatura (°C)
        histeresis: 1.0,       // banda de histéresis (± °C)
        tApagado_s: 120,       // tiempo que lleva apagado el compresor
        modo: 'REPOSO'         // APAGADO | REPOSO | ENFRIANDO | ESPERA | FALLA
    };
}

// Acumuladores para los KPI.
function kpiInicial() {
    return {
        tTotal_s: 0, tEnRango_s: 0, tFalla_s: 0,
        energia_kWh: 0, ciclos: 0,
        fueraDeRango: false, inicioExcursion_s: 0,
        recuperaciones: 0, sumaRecuperacion_min: 0, ultimaRecuperacion_min: 0
    };
}

// Contadores de identificadores únicos y temporizadores de las alarmas.
const memoriaInicial = () => ({ alarmaSeq: 0, comandoSeq: 0, temporizadores: { RANGO: 0, PUERTA: 0, FALLA: 0 } });

// Se intenta leer el archivo persistido, salvo que se pida reinicio.
let previo = null;
if (!msg.reset && typeof msg.payload === 'string') {
    try { previo = JSON.parse(msg.payload); }           // JSON.parse convierte texto a objeto
    catch (e) { node.warn('Persistencia ilegible: se usa el estado inicial'); }
    // Un archivo de una versión anterior del modelo no se reutiliza.
    if (previo && previo.version !== params.version) previo = null;
}

// Reinicio solo de los KPI: el proceso sigue igual.
if (msg.reset === 'kpi') {
    global.set('b10_kpi', kpiInicial());
    node.status({ fill: 'blue', shape: 'dot', text: 'KPI reiniciados' });
    msg.payload = { evento: 'KPI_REINICIADOS', timestamp: new Date().toISOString() };
    return msg;
}

// Object.assign mezcla los valores guardados sobre los iniciales: así un
// archivo antiguo sin algún campo nuevo no rompe el simulador.
global.set('b10_params', params);
global.set('b10_estado', Object.assign(estadoInicial(), previo ? previo.estado : {}));
global.set('b10_kpi', Object.assign(kpiInicial(), previo ? previo.kpi : {}));
global.set('b10_memoria', Object.assign(memoriaInicial(), previo ? previo.memoria : {}));
global.set('b10_alarmas', previo && previo.alarmas ? previo.alarmas : []);
global.set('b10_historial', previo && previo.historial ? previo.historial : []);
global.set('b10_solicitudes', msg.reset || !previo || !previo.solicitudes ? [] : previo.solicitudes);

const origen = msg.reset ? 'reinicio total por comando' : (previo ? 'archivo de persistencia' : 'valores iniciales');
node.status({ fill: 'green', shape: 'dot', text: 'Estado: ' + origen });
msg.payload = { evento: 'SIMULADOR_INICIADO', origen, timestamp: new Date().toISOString() };
return msg;

// =====================================================================
// MODELO DINÁMICO: integra dos balances de energía con el método de Euler.
//
// Aire de la cámara:
//   C · dT/dt = Qparedes + Qpuerta + Qinterna + Qproducto - Qfrig
// Producto (las cajas guardadas):
//   Cprod · dTprod/dt = -Qproducto
//   Qproducto = hCaja · cajas · (Tprod - T)
//
// Una caja caliente entrega calor al aire hasta igualar su temperatura;
// por eso un lote caliente sube la carga térmica y luego se va enfriando.
// El aleatorio se usa solo como perturbación de clima y de carga interna.
// =====================================================================
const p = global.get('b10_params');   // parámetros constantes
const e = global.get('b10_estado');   // estado anterior
if (!p || !e) return null;            // todavía no termina la inicialización

const dt = p.dtReal_s * e.escala;     // segundos simulados de este paso
e.tSim_s += dt;

// Math.random() da 0..1; restando 0.5 queda un ruido centrado en cero.
const ruido = (amplitud) => (Math.random() - 0.5) * 2 * amplitud;
// Limita un valor entre un mínimo y un máximo.
const limitar = (v, min, max) => Math.min(max, Math.max(min, v));

// 1) Temperatura exterior: ciclo diario senoidal + perturbación lenta.
e.ruidoExt = limitar(e.ruidoExt * 0.98 + ruido(0.05), -1, 1);
e.tExt = p.tExtBase_C + p.tExtAmplitud_C * Math.sin(2 * Math.PI * e.tSim_s / 86400) + e.ruidoExt;

// 2) Ganancias de calor en kW.
const dT = e.tExt - e.tInt;                                  // diferencia con el exterior
const qParedes = p.UAparedes_kWK * dT;                       // conducción por paredes
const qPuerta = e.puertaAbierta ? p.UApuerta_kWK * dT : 0;   // infiltración por la puerta
const qInterna = Math.max(0, p.qInterna_kW + ruido(0.05)) + e.cargaExtra_kW; // luces + montacargas/equipos
const qProducto = e.cajas > 0 ? p.hCaja_kWK * e.cajas * (e.tProd - e.tInt) : 0;
const qGanancias = qParedes + qPuerta + qInterna + qProducto;

// 3) Compresor: la potencia frigorífica converge a su objetivo (primer orden).
//    Math.exp da la solución exacta, estable para cualquier dt.
const qObjetivo = e.compresorOn ? p.qNominal_kW : 0;
e.qFrig = qObjetivo + (e.qFrig - qObjetivo) * Math.exp(-dt / p.tauCompresor_s);
if (e.qFrig < 0.01) e.qFrig = 0;
e.pElec = e.compresorOn ? e.qFrig / p.COP : 0;               // potencia eléctrica = frío / COP

// 4) Balance del aire (Euler): kW · s / (kJ/K) = K.
e.tInt += (qGanancias - e.qFrig) * dt / p.capacidadTermica_kJK;

// 5) Balance del producto: pierde el mismo calor que entrega al aire.
if (e.cajas > 0) {
    const cProd = e.cajas * p.cajaMasa_kg * p.cajaCp_kJkgK;  // kJ/K de todas las cajas
    e.tProd -= qProducto * dt / cProd;
} else {
    e.tProd = e.tInt;                                        // sin cajas no hay producto que medir
}

// 6) Humedad: el aire que entra humedece y el evaporador condensa.
const dH = (e.puertaAbierta ? p.kHumPuerta_s : 0) * (p.hEntrada_pct - e.hum)
    + p.kHumParedes_s * (p.hEntrada_pct - e.hum)
    + p.kHumEvaporador_s * (e.qFrig / p.qNominal_kW) * (p.hEvaporador_pct - e.hum);
e.hum = limitar(e.hum + dH * dt + ruido(0.05), 40, 100);

// 7) Tiempo que lleva abierta la puerta (se usa en la alarma).
e.tPuerta_s = e.puertaAbierta ? e.tPuerta_s + dt : 0;

// Desglose para la vista de ingeniería.
const r = v => +v.toFixed(2);
e.balance = {
    qParedes: r(qParedes), qPuerta: r(qPuerta), qInterna: r(qInterna),
    qProducto: r(qProducto), qGanancias: r(qGanancias), qFrig: r(e.qFrig)
};

global.set('b10_estado', e);
node.status({ fill: e.compresorOn ? 'blue' : 'grey', shape: 'dot', text: e.tInt.toFixed(2) + ' °C | ' + e.modo + ' | x' + e.escala });
msg.payload = { tSim_s: e.tSim_s, tInt: r(e.tInt), tProd: r(e.tProd), cajas: e.cajas, tExt: r(e.tExt), hum: +e.hum.toFixed(1), qFrig: r(e.qFrig) };
return msg;

// =====================================================================
// PERSISTENCIA: junta todo en un texto JSON para el nodo file.
// Al reiniciar Node-RED, el nodo Inicializar lee este mismo archivo.
// =====================================================================
if (!global.get('b10_estado')) return null;
msg.payload = JSON.stringify({
    version: global.get('b10_params').version,
    guardado: new Date().toISOString(),
    estado: global.get('b10_estado'),
    kpi: global.get('b10_kpi'),
    memoria: global.get('b10_memoria'),
    alarmas: global.get('b10_alarmas'),
    historial: global.get('b10_historial'),
    solicitudes: global.get('b10_solicitudes')
});
return msg;

// GET /api/B10/telemetry -> las cuatro variables obligatorias con su unidad.
if (!global.get('b10_estado')) {
    msg.error = { statusCode: 503, codigo: 'INICIANDO', mensaje: 'El simulador está arrancando' };
    return msg;
}
const e = global.get('b10_estado');
const r = (v, d) => +v.toFixed(d);   // redondea a d decimales y deja número
msg.statusCode = 200;
msg.payload = {
    simTime_s: e.tSim_s,
    variables: {
        temperaturaInterior: { valor: r(e.tInt, 2), unidad: '°C' },
        temperaturaExterior: { valor: r(e.tExt, 2), unidad: '°C' },
        humedad: { valor: r(e.hum, 1), unidad: '%' },
        potenciaFrigorifica: { valor: r(e.qFrig, 2), unidad: 'kW' }
    },
    potenciaElectrica: { valor: r(e.pElec, 2), unidad: 'kW' },
    producto: { cajas: e.cajas, temperatura: { valor: r(e.tProd, 2), unidad: '°C' } },
    cargaTermicaTotal: { valor: e.balance ? e.balance.qGanancias : 0, unidad: 'kW' },
    balance_kW: e.balance || null
};
return msg;

// GET /api/B10/status -> estado de actuadores, modo y consigna.
if (!global.get('b10_estado')) {
    msg.error = { statusCode: 503, codigo: 'INICIANDO', mensaje: 'El simulador está arrancando' };
    return msg;
}
const p = global.get('b10_params');
const e = global.get('b10_estado');
const alarmas = global.get('b10_alarmas');
msg.statusCode = 200;
msg.payload = {
    modo: e.modo,
    refrigeracionActiva: e.refrigHabilitada,
    demandaFrio: e.demandaFrio,
    compresorEncendido: e.compresorOn,
    puertaAbierta: e.puertaAbierta,
    puertaAbierta_s: e.tPuerta_s,
    fallaCompresor: e.fallaCompresor,
    cargaExtra_kW: e.cargaExtra_kW,
    cargaExtraMax_kW: p.cargaExtraMax_kW,
    cajas: e.cajas,
    capacidadCajas: p.capacidadCajas,
    cajasEntrando: e.cajasEntrando,
    temperaturaProducto_C: +e.tProd.toFixed(2),
    consigna_C: e.consigna,
    histeresis_C: e.histeresis,
    rangoAceptable_C: [p.tMin_C, p.tMax_C],
    escalaTiempo: e.escala,
    escalasPermitidas: p.escalasPermitidas,
    alarmasActivas: alarmas.filter(a => a.estado === 'ACTIVA').length,
    alarmasSinReconocer: alarmas.filter(a => !a.reconocida).length
};
return msg;

// GET /api/B10/kpis -> los cinco KPI con fórmula y unidad.
if (!global.get('b10_estado')) {
    msg.error = { statusCode: 503, codigo: 'INICIANDO', mensaje: 'El simulador está arrancando' };
    return msg;
}
const k = global.get('b10_kpi');
const total = k.tTotal_s || 1;                  // evita dividir entre cero al arrancar
const r = (v, d) => +v.toFixed(d);
const promedio = k.recuperaciones ? k.sumaRecuperacion_min / k.recuperaciones : 0;
msg.statusCode = 200;
msg.payload = {
    tiempoObservado_min: r(k.tTotal_s / 60, 1),
    kpis: [
        { id: 'tiempoEnRango', nombre: 'Tiempo dentro de rango', valor: r(100 * k.tEnRango_s / total, 1), unidad: '%', formula: 'tEnRango / tTotal · 100' },
        { id: 'energia', nombre: 'Energía estimada', valor: r(k.energia_kWh, 3), unidad: 'kWh', formula: '∑ Pelec · Δt / 3600' },
        { id: 'ciclos', nombre: 'Ciclos del compresor', valor: k.ciclos, unidad: 'n', formula: 'cuenta de arranques apagado→encendido' },
        { id: 'recuperacion', nombre: 'Tiempo de recuperación', valor: r(k.ultimaRecuperacion_min, 1), unidad: 'min', formula: 'tRegreso al rango - tSalida del rango (última)', promedio_min: r(promedio, 1), enExcursion: k.fueraDeRango },
        { id: 'disponibilidad', nombre: 'Disponibilidad', valor: r(100 * (total - k.tFalla_s) / total, 1), unidad: '%', formula: '(tTotal - tFalla) / tTotal · 100' }
    ]
};
return msg;

// GET /api/B10/history?ventana_min=60&variables=tInt,hum
if (!global.get('b10_estado')) {
    msg.error = { statusCode: 503, codigo: 'INICIANDO', mensaje: 'El simulador está arrancando' };
    return msg;
}
// La ventana temporal es configurable y está en minutos simulados.
const h = global.get('b10_historial');
const validas = ['tInt', 'tProd', 'tExt', 'hum', 'qFrig', 'pElec', 'comp', 'puerta'];
const q = msg.req.query;                      // parámetros que vienen tras el ?

const ventana = q.ventana_min === undefined ? 60 : Number(q.ventana_min);
if (!Number.isFinite(ventana) || ventana < 1 || ventana > 720) {
    msg.error = { statusCode: 400, codigo: 'VENTANA_INVALIDA', mensaje: 'ventana_min debe estar entre 1 y 720' };
    return msg;
}
const pedidas = q.variables ? String(q.variables).split(',') : validas;
const desconocida = pedidas.find(v => !validas.includes(v));
if (desconocida) {
    msg.error = { statusCode: 400, codigo: 'VARIABLE_DESCONOCIDA', mensaje: 'No existe la variable ' + desconocida + '. Use: ' + validas.join(', ') };
    return msg;
}

const ultimoS = h.length ? h[h.length - 1].s : 0;
const desde = ultimoS - ventana * 60;          // inicio de la ventana
const puntos = h.filter(x => x.s >= desde).map(x => {
    const fila = { timestamp: x.t, simTime_s: x.s };
    pedidas.forEach(v => { fila[v] = x[v]; });  // copia solo lo pedido
    return fila;
});
msg.statusCode = 200;
msg.payload = {
    ventana_min: ventana,
    unidades: { tInt: '°C', tProd: '°C', tExt: '°C', hum: '%', qFrig: 'kW', pElec: 'kW', comp: '0/1', puerta: '0/1' },
    n: puntos.length,
    puntos
};
return msg;

// GET /api/B10/alarms -> registro; ?estado=ACTIVA filtra solo las activas.
if (!global.get('b10_estado')) {
    msg.error = { statusCode: 503, codigo: 'INICIANDO', mensaje: 'El simulador está arrancando' };
    return msg;
}
let lista = global.get('b10_alarmas');
if (msg.req.query.estado) lista = lista.filter(a => a.estado === String(msg.req.query.estado).toUpperCase());
msg.statusCode = 200;
msg.payload = { n: lista.length, alarmas: lista };
return msg;

// GET /api/B10/logs -> código de respuesta y tiempo de cada solicitud de control.
if (!global.get('b10_estado')) {
    msg.error = { statusCode: 503, codigo: 'INICIANDO', mensaje: 'El simulador está arrancando' };
    return msg;
}
const lista = global.get('b10_solicitudes');
msg.statusCode = 200;
msg.payload = { n: lista.length, solicitudes: lista.slice(0, 100) };
return msg;

// =====================================================================
// POST /api/B10/commands   Cuerpo: { "command": "ABRIR_PUERTA", "params": {} }
//   201 comando aceptado | 400 solicitud mal formada | 409 incompatible
// Salida 1: respuesta HTTP. Salida 2: reinicio (total o solo KPI).
// =====================================================================
msg.t0 = Date.now();      // hora de llegada, para medir el tiempo de respuesta
msg.esControl = true;
if (!global.get('b10_estado')) {
    msg.error = { statusCode: 503, codigo: 'INICIANDO', mensaje: 'El simulador está arrancando' };
    return [msg, null];
}
const p = global.get('b10_params');
const e = global.get('b10_estado');
const m = global.get('b10_memoria');

const falla = (statusCode, codigo, mensaje) => {       // atajo para responder errores
    msg.error = { statusCode, codigo, mensaje };
    return [msg, null];
};
// Convierte a número y verifica que sea un número real.
const numero = v => (v === undefined || v === null || v === '') ? NaN : Number(v);

const cuerpo = msg.payload;
if (!cuerpo || typeof cuerpo !== 'object' || typeof cuerpo.command !== 'string') {
    return falla(400, 'CUERPO_INVALIDO', 'Envíe JSON con el campo command');
}
const comando = cuerpo.command.toUpperCase();
const parametros = cuerpo.params || {};
msg.comando = comando;

let reinicio = null;

// Cada caso primero revisa si es compatible con el estado y luego actúa.
switch (comando) {
    case 'ACTIVAR_REFRIGERACION':
        if (e.refrigHabilitada) return falla(409, 'YA_ACTIVA', 'La refrigeración ya está activa');
        if (e.fallaCompresor) return falla(409, 'COMPRESOR_EN_FALLA', 'No se puede activar con el compresor en falla');
        e.refrigHabilitada = true;
        break;
    case 'DESACTIVAR_REFRIGERACION':
        if (!e.refrigHabilitada) return falla(409, 'YA_INACTIVA', 'La refrigeración ya está apagada');
        e.refrigHabilitada = false;
        break;
    case 'ABRIR_PUERTA':
        if (e.puertaAbierta) return falla(409, 'PUERTA_YA_ABIERTA', 'La puerta ya está abierta');
        e.puertaAbierta = true;
        break;
    case 'CERRAR_PUERTA':
        if (!e.puertaAbierta) return falla(409, 'PUERTA_YA_CERRADA', 'La puerta ya está cerrada');
        e.puertaAbierta = false;
        break;
    case 'AJUSTAR_CARGA': {
        // Carga térmica adicional: montacargas o equipos trabajando dentro.
        const kw = numero(parametros.kw);
        if (!Number.isFinite(kw) || kw < 0 || kw > p.cargaExtraMax_kW) {
            return falla(400, 'CARGA_FUERA_DE_RANGO', 'kw debe estar entre 0 y ' + p.cargaExtraMax_kW);
        }
        e.cargaExtra_kW = kw;
        break;
    }
    case 'INGRESAR_PRODUCTO': {
        const cajas = numero(parametros.cajas);
        const temp = parametros.temperatura === undefined ? p.tIngresoDefecto_C : numero(parametros.temperatura);
        if (!Number.isInteger(cajas) || cajas < 1) return falla(400, 'CAJAS_INVALIDAS', 'cajas debe ser un entero mayor que 0');
        if (!Number.isFinite(temp) || temp < p.tIngresoMin_C || temp > p.tIngresoMax_C) {
            return falla(400, 'TEMPERATURA_INVALIDA', 'temperatura debe estar entre ' + p.tIngresoMin_C + ' y ' + p.tIngresoMax_C + ' °C');
        }
        if (!e.puertaAbierta) return falla(409, 'PUERTA_CERRADA', 'Abra la puerta para ingresar producto');
        if (e.cajas + cajas > p.capacidadCajas) {
            return falla(409, 'SIN_ESPACIO', 'Solo caben ' + (p.capacidadCajas - e.cajas) + ' cajas más');
        }
        // Mezcla de energía: la temperatura media se pondera por número de cajas.
        e.tProd = e.cajas ? (e.tProd * e.cajas + temp * cajas) / (e.cajas + cajas) : temp;
        e.cajas += cajas;
        e.cajasEntrando = cajas;
        break;
    }
    case 'RETIRAR_PRODUCTO': {
        const cajas = numero(parametros.cajas);
        if (!Number.isInteger(cajas) || cajas < 1) return falla(400, 'CAJAS_INVALIDAS', 'cajas debe ser un entero mayor que 0');
        if (!e.puertaAbierta) return falla(409, 'PUERTA_CERRADA', 'Abra la puerta para retirar producto');
        if (cajas > e.cajas) return falla(409, 'PRODUCTO_INSUFICIENTE', 'Solo hay ' + e.cajas + ' cajas');
        e.cajas -= cajas;
        e.cajasEntrando = 0;
        break;
    }
    case 'FALLAR_COMPRESOR':
        if (e.fallaCompresor) return falla(409, 'FALLA_ACTIVA', 'El compresor ya está en falla');
        e.fallaCompresor = true;
        break;
    case 'REPARAR_COMPRESOR':
        if (!e.fallaCompresor) return falla(409, 'SIN_FALLA', 'El compresor no está en falla');
        e.fallaCompresor = false;
        break;
    case 'AJUSTAR_VELOCIDAD': {
        const escala = numero(parametros.escala);
        if (!p.escalasPermitidas.includes(escala)) {
            return falla(400, 'VELOCIDAD_INVALIDA', 'escala debe ser una de: ' + p.escalasPermitidas.join(', '));
        }
        e.escala = escala;
        break;
    }
    case 'REINICIAR_KPI':
        reinicio = { reset: 'kpi' };
        break;
    case 'REINICIAR':
        reinicio = { reset: 'todo' };
        break;
    default:
        return falla(400, 'COMANDO_DESCONOCIDO', 'Comando no soportado: ' + comando);
}

m.comandoSeq += 1;
global.set('b10_estado', e);
global.set('b10_memoria', m);

msg.statusCode = 201;      // 201 Created: se creó un registro de comando
msg.payload = {
    commandId: 'CMD-' + String(m.comandoSeq).padStart(5, '0'),
    command: comando,
    resultado: 'ACEPTADO',
    params: parametros
};
return [msg, reinicio];

// =====================================================================
// PUT /api/B10/setpoint   Cuerpo: { "value": 4.5 }
//   200 aplicado | 400 fuera de rango | 409 incompatible con el estado
// =====================================================================
const p = global.get('b10_params');
const e = global.get('b10_estado');
msg.t0 = Date.now();      // hora de llegada, para medir el tiempo de respuesta
msg.esControl = true;
if (!global.get('b10_estado')) {
    msg.error = { statusCode: 503, codigo: 'INICIANDO', mensaje: 'El simulador está arrancando' };
    return msg;
}

const valor = msg.payload && typeof msg.payload === 'object' ? msg.payload.value : undefined;
msg.comando = 'CONSIGNA ' + valor;

if (typeof valor !== 'number' || !Number.isFinite(valor)) {
    msg.error = { statusCode: 400, codigo: 'CONSIGNA_INVALIDA', mensaje: 'Envíe JSON con value numérico, por ejemplo {"value": 4}' };
} else if (valor < p.consignaMin_C || valor > p.consignaMax_C) {
    msg.error = { statusCode: 400, codigo: 'CONSIGNA_FUERA_DE_RANGO', mensaje: 'La consigna debe estar entre ' + p.consignaMin_C + ' y ' + p.consignaMax_C + ' °C' };
} else if (e.fallaCompresor) {
    msg.error = { statusCode: 409, codigo: 'COMPRESOR_EN_FALLA', mensaje: 'No se cambia la consigna con el compresor en falla' };
} else {
    const anterior = e.consigna;
    e.consigna = valor;
    global.set('b10_estado', e);
    msg.statusCode = 200;
    msg.payload = { resultado: 'CONSIGNA_APLICADA', consignaAnterior_C: anterior, consigna_C: valor, unidad: '°C' };
}
return msg;

// POST /api/B10/alarms/:id/ack -> reconocimiento de una alarma.
// :id llega en msg.req.params. 404 si no existe, 409 si ya estaba reconocida.
const registro = global.get('b10_alarmas');
const alarma = registro.find(a => a.id === msg.req.params.id);
msg.t0 = Date.now();      // hora de llegada, para medir el tiempo de respuesta
msg.esControl = true;
if (!global.get('b10_estado')) {
    msg.error = { statusCode: 503, codigo: 'INICIANDO', mensaje: 'El simulador está arrancando' };
    return msg;
}
msg.comando = 'RECONOCER ' + msg.req.params.id;
if (!alarma) {
    msg.error = { statusCode: 404, codigo: 'ALARMA_NO_ENCONTRADA', mensaje: 'No existe la alarma ' + msg.req.params.id };
    return msg;
}
if (alarma.reconocida) {
    msg.error = { statusCode: 409, codigo: 'ALARMA_YA_RECONOCIDA', mensaje: 'La alarma ya fue reconocida a las ' + alarma.horaReconocimiento };
    return msg;
}
alarma.reconocida = true;
alarma.horaReconocimiento = new Date().toISOString();
global.set('b10_alarmas', registro);
msg.statusCode = 200;
msg.payload = { resultado: 'ALARMA_RECONOCIDA', alarma };
return msg;

// =====================================================================
// RESPONDER: da el mismo formato a todas las respuestas de la API.
// Agrega deviceId y timestamp ISO 8601, convierte msg.error en cuerpo
// de error y registra cada solicitud de control con código y tiempo.
// =====================================================================
const p = global.get('b10_params') || { deviceId: 'B10-CAMARA-01', registrosMax: 200 };
const ahora = new Date();

if (msg.error) {
    msg.statusCode = msg.error.statusCode;
    msg.payload = { error: { codigo: msg.error.codigo, mensaje: msg.error.mensaje } };
}
// ... expande las propiedades del objeto dentro del nuevo objeto.
msg.payload = { deviceId: p.deviceId, timestamp: ahora.toISOString(), ...msg.payload };
msg.headers = { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store' };

if (msg.esControl) {
    const lista = global.get('b10_solicitudes') || [];
    const registro = {
        timestamp: ahora.toISOString(),
        metodo: msg.req.method,
        ruta: msg.req.originalUrl,
        comando: msg.comando || '-',
        codigo: msg.statusCode,
        tiempo_ms: ahora.getTime() - msg.t0     // msg.t0 lo puso la función de la ruta
    };
    lista.unshift(registro);
    if (lista.length > p.registrosMax) lista.splice(p.registrosMax);
    global.set('b10_solicitudes', lista);
    node.status({ fill: msg.statusCode < 300 ? 'green' : 'red', shape: 'dot', text: registro.metodo + ' ' + registro.comando + ' -> ' + registro.codigo });
    return [msg, { payload: registro }];     // salida 2: debug de la solicitud
}
return [msg, null];

// Cualquier otra ruta bajo /api/B10/ responde 404 en JSON.
msg.t0 = Date.now();
msg.esControl = msg.req.method !== 'GET';
msg.comando = msg.req.method + ' ' + msg.req.originalUrl;
msg.error = { statusCode: 404, codigo: 'RUTA_NO_ENCONTRADA', mensaje: 'No existe ' + msg.req.method + ' ' + msg.req.originalUrl };
return msg;

// =====================================================================
// CONTROL CON HISTÉRESIS (termostato de dos puntos).
//   T >= consigna + h  -> pedir frío
//   T <= consigna - h  -> dejar de pedir frío
//   entre ambos        -> mantener la decisión anterior (evita ciclado)
// Salida 1: sigue el ciclo normal. Salida 2: evento de cambio del compresor.
// =====================================================================
const p = global.get('b10_params');
const e = global.get('b10_estado');
if (!p || !e) return null;
const dt = p.dtReal_s * e.escala;     // segundos simulados de este paso

const antes = e.compresorOn;              // se guarda para detectar cambios

// Paso 1: decisión de la histéresis.
if (!e.refrigHabilitada) e.demandaFrio = false;
else if (e.tInt >= e.consigna + e.histeresis) e.demandaFrio = true;
else if (e.tInt <= e.consigna - e.histeresis) e.demandaFrio = false;

// Paso 2: protección anti ciclado, el compresor debe descansar un mínimo.
e.tApagado_s = e.compresorOn ? 0 : e.tApagado_s + dt;
const puedeArrancar = e.compresorOn || e.tApagado_s >= p.tMinApagado_s;

// Paso 3: orden real al compresor; una falla impide que gire.
e.compresorOn = e.demandaFrio && !e.fallaCompresor && puedeArrancar;

// Paso 4: modo para la interfaz.
if (e.fallaCompresor) e.modo = 'FALLA';
else if (!e.refrigHabilitada) e.modo = 'APAGADO';
else if (e.compresorOn) e.modo = 'ENFRIANDO';
else if (e.demandaFrio) e.modo = 'ESPERA';
else e.modo = 'REPOSO';

global.set('b10_estado', e);

let evento = null;
if (antes !== e.compresorOn) {
    evento = { payload: {
        evento: e.compresorOn ? 'COMPRESOR_ARRANCA' : 'COMPRESOR_PARA',
        tInt: +e.tInt.toFixed(2), consigna: e.consigna, histeresis: e.histeresis,
        timestamp: new Date().toISOString()
    } };
}
return [msg, evento];   // el arreglo reparte un mensaje por cada salida

// =====================================================================
// ALARMAS: evalúa tres condiciones y mantiene su registro.
// Cada alarma tiene un retardo para evitar disparos por ruido momentáneo.
// Salida 1: sigue el ciclo normal. Salida 2: evento de alarma.
// =====================================================================
const p = global.get('b10_params');
const e = global.get('b10_estado');
const m = global.get('b10_memoria');
const registro = global.get('b10_alarmas');
if (!p || !e) return null;
const dt = p.dtReal_s * e.escala;     // segundos simulados de este paso

// Arreglo con la definición de las tres alarmas exigidas.
const definiciones = [
    {
        codigo: 'RANGO', severidad: 'ALTA', retardo: p.alarmaRangoRetardo_s,
        condicion: 'T < ' + p.tMin_C + ' °C o T > ' + p.tMax_C + ' °C',
        activa: e.tInt < p.tMin_C || e.tInt > p.tMax_C,
        mensaje: 'Temperatura fuera de rango', valor: +e.tInt.toFixed(2), unidad: '°C'
    },
    {
        codigo: 'PUERTA', severidad: 'MEDIA', retardo: 0,
        condicion: 'Puerta abierta >= ' + p.alarmaPuertaRetardo_s + ' s',
        activa: e.tPuerta_s >= p.alarmaPuertaRetardo_s,
        mensaje: 'Puerta abierta prolongada', valor: e.tPuerta_s, unidad: 's'
    },
    {
        // Se detecta por el efecto (hay demanda y no hay frío), no leyendo la falla inyectada.
        codigo: 'FALLA', severidad: 'CRITICA', retardo: p.alarmaFallaRetardo_s,
        condicion: 'Demanda de frío con Qfrig < ' + p.qMinimoDetectable_kW + ' kW',
        activa: e.demandaFrio && e.qFrig < p.qMinimoDetectable_kW,
        mensaje: 'Falla de refrigeración', valor: +e.qFrig.toFixed(2), unidad: 'kW'
    }
];

const eventos = [];
const ahora = new Date().toISOString();

for (const d of definiciones) {
    // Temporizador: suma mientras la condición siga, se reinicia si desaparece.
    m.temporizadores[d.codigo] = d.activa ? m.temporizadores[d.codigo] + dt : 0;
    const dispara = d.activa && m.temporizadores[d.codigo] >= d.retardo;

    // .find devuelve la alarma activa de este código, si existe.
    const abierta = registro.find(a => a.codigo === d.codigo && a.estado === 'ACTIVA');

    if (dispara && !abierta) {
        m.alarmaSeq += 1;
        const alarma = {
            id: 'ALM-' + String(m.alarmaSeq).padStart(4, '0'), // padStart rellena: ALM-0007
            codigo: d.codigo, mensaje: d.mensaje, severidad: d.severidad,
            condicion: d.condicion, valor: d.valor, unidad: d.unidad,
            estado: 'ACTIVA', horaActivacion: ahora, horaNormalizacion: null,
            reconocida: false, horaReconocimiento: null
        };
        registro.unshift(alarma);          // unshift la pone de primera (más reciente)
        eventos.push({ evento: 'ALARMA_ACTIVADA', ...alarma });
    }
    if (!d.activa && abierta) {
        abierta.estado = 'NORMALIZADA';
        abierta.horaNormalizacion = ahora;
        eventos.push({ evento: 'ALARMA_NORMALIZADA', id: abierta.id, codigo: abierta.codigo, timestamp: ahora });
    }
}

// .splice recorta el registro para que el archivo no crezca sin límite.
if (registro.length > p.registrosMax) registro.splice(p.registrosMax);

global.set('b10_alarmas', registro);
global.set('b10_memoria', m);

const activas = registro.filter(a => a.estado === 'ACTIVA').length;
node.status({ fill: activas ? 'red' : 'green', shape: activas ? 'ring' : 'dot', text: activas + ' alarma(s) activa(s)' });

// Una lista en una salida envía un mensaje por cada elemento.
return [msg, eventos.map(ev => ({ payload: ev }))];

// =====================================================================
// KPI E HISTÓRICO: actualiza los acumuladores y guarda un punto por tick.
// Los tiempos son simulados, igual que la energía.
// =====================================================================
const p = global.get('b10_params');
const e = global.get('b10_estado');
const k = global.get('b10_kpi');
const h = global.get('b10_historial');
if (!p || !e) return null;
const dt = p.dtReal_s * e.escala;     // segundos simulados de este paso

const enRango = e.tInt >= p.tMin_C && e.tInt <= p.tMax_C;

k.tTotal_s += dt;
if (enRango) k.tEnRango_s += dt;
if (e.fallaCompresor) k.tFalla_s += dt;

// Energía = integral de la potencia: kW · (s / 3600) = kWh.
k.energia_kWh += e.pElec * dt / 3600;

// Ciclo = cada transición apagado -> encendido del compresor.
if (e.compresorOn && !k.compresorAnterior) k.ciclos += 1;
k.compresorAnterior = e.compresorOn;

// Tiempo de recuperación: desde que sale del rango hasta que regresa.
if (!enRango && !k.fueraDeRango) {
    k.fueraDeRango = true;
    k.inicioExcursion_s = e.tSim_s;
}
if (enRango && k.fueraDeRango) {
    k.fueraDeRango = false;
    k.ultimaRecuperacion_min = (e.tSim_s - k.inicioExcursion_s) / 60;
    k.sumaRecuperacion_min += k.ultimaRecuperacion_min;
    k.recuperaciones += 1;
}

// Punto del histórico con nombres cortos para que el archivo no pese mucho.
h.push({
    t: new Date().toISOString(), s: e.tSim_s,
    tInt: +e.tInt.toFixed(2), tProd: +e.tProd.toFixed(2), tExt: +e.tExt.toFixed(2), hum: +e.hum.toFixed(1),
    qFrig: +e.qFrig.toFixed(2), pElec: +e.pElec.toFixed(2),
    comp: e.compresorOn ? 1 : 0, puerta: e.puertaAbierta ? 1 : 0
});
if (h.length > p.historialMax) h.shift();   // shift elimina el punto más antiguo

global.set('b10_kpi', k);
global.set('b10_historial', h);
return msg;

// Separa la respuesta HTTP de /telemetry: un mensaje por gauge.
if (!msg.payload || !msg.payload.variables) return null;   // API caída
const t = msg.payload;
const v = t.variables;
return [
    { payload: v.temperaturaInterior.valor },
    { payload: v.temperaturaExterior.valor },
    { payload: v.humedad.valor },
    { payload: v.potenciaFrigorifica.valor },
    { payload: t.producto.temperatura.valor },
    { payload: t.cargaTermicaTotal.valor }
];

// Convierte la respuesta HTTP de /status en textos para el panel.
// También guarda la respuesta en esta pestaña para los botones de alternar
// y sincroniza los controles con el estado real.
const s = msg.payload;
if (!s || !s.modo) return null;
flow.set('ultimoEstado', s);     // copia de la respuesta HTTP (no lee el simulador)

// msg.ui_update cambia el texto, el icono y el color del botón sin pulsarlo.
const boton = (label, icon, buttonColor) => ({ ui_update: { label, icon, buttonColor } });
return [
    { payload: s.modo },
    { payload: s.compresorEncendido ? 'Encendido' : 'Apagado' },
    { payload: s.puertaAbierta ? 'Abierta' : 'Cerrada' },
    { payload: s.consigna_C + ' °C ± ' + s.histeresis_C + ' °C' },
    { payload: s.alarmasActivas + ' activas, ' + s.alarmasSinReconocer + ' sin reconocer' },
    { payload: s.cajas + ' de ' + s.capacidadCajas + ' cajas a ' + s.temperaturaProducto_C.toFixed(1) + ' °C' },
    { payload: '1 s real = ' + s.escalaTiempo + ' s simulados' },
    { payload: s.consigna_C, topic: 'consigna' },      // campo numérico de consigna
    { payload: s.cargaExtra_kW, topic: 'carga' },      // slider de carga
    { payload: s.escalaTiempo, topic: 'velocidad' },   // lista de velocidad
    s.refrigeracionActiva ? boton('Apagar refrigeración', 'power', '') : boton('Activar refrigeración', 'snowflake', ''),
    s.puertaAbierta ? boton('Cerrar puerta', 'door', '#b8742f') : boton('Abrir puerta', 'door-open', ''),
    s.fallaCompresor ? boton('Reparar compresor', 'wrench', '#b33a3a') : boton('Provocar falla del compresor', 'alert', '')
];

// Un solo botón por acción: decide el comando según el último estado
// recibido por HTTP (guardado por "Repartir estado" en esta pestaña).
const s = flow.get('ultimoEstado');
if (!s) return null;                       // aún no llega la primera respuesta
const comandos = {
    refrigeracion: s.refrigeracionActiva ? 'DESACTIVAR_REFRIGERACION' : 'ACTIVAR_REFRIGERACION',
    puerta: s.puertaAbierta ? 'CERRAR_PUERTA' : 'ABRIR_PUERTA',
    falla: s.fallaCompresor ? 'REPARAR_COMPRESOR' : 'FALLAR_COMPRESOR'
};
msg.payload = { command: comandos[msg.topic] };
return msg;

// El número del panel se envía como JSON al PUT /setpoint.
msg.payload = { value: Number(msg.payload) };
return msg;

// El slider de carga térmica envía el comando AJUSTAR_CARGA.
msg.payload = { command: 'AJUSTAR_CARGA', params: { kw: Number(msg.payload) } };
return msg;

// Al arrancar, deja los sliders y las variables del lote con el mismo valor.
flow.set('cajasLote', 4);
flow.set('tLote', 25);
return [{ payload: 4 }, { payload: 25 }];

// Los botones de producto usan los valores elegidos en los sliders.
// flow.get lee variables de esta pestaña de presentación (no del simulador).
const cajas = flow.get('cajasLote') || 4;
const temperatura = flow.get('tLote') === undefined ? 25 : flow.get('tLote');
msg.payload = msg.topic === 'retirar'
    ? { command: 'RETIRAR_PRODUCTO', params: { cajas } }
    : { command: 'INGRESAR_PRODUCTO', params: { cajas, temperatura } };
return msg;

// La lista de velocidad envía el comando AJUSTAR_VELOCIDAD.
msg.payload = { command: 'AJUSTAR_VELOCIDAD', params: { escala: Number(msg.payload) } };
return msg;

// Muestra al operador el código HTTP que devolvió la API.
// Salida 1: texto para la notificación y el debug.
// Salida 2: msg.reset borra la memoria de los nodos "Solo si cambia"; así,
// en el siguiente polling los controles vuelven a mostrar el valor real de
// la API (por ejemplo, la consigna regresa a 4 si se rechazó un 100).
const r = msg.payload && msg.payload.error ? msg.payload.error.mensaje : (msg.payload && msg.payload.resultado) || 'Sin respuesta';
msg.payload = 'HTTP ' + (msg.statusCode || '---') + ': ' + r;
return [msg, { reset: true }];

// Arma la URL del histórico con la ventana elegida en el dashboard.
const ventana = flow.get('ventana_min') || 30;
msg.url = 'http://127.0.0.1:1880/api/B10/history?variables=tInt,tExt,hum,qFrig&ventana_min=' + ventana;
return msg;

// Convierte /history en arreglos {x, y, series} para los cuatro ui-chart.
if (!msg.payload || !msg.payload.puntos || msg.payload.puntos.length === 0) return null;
const p = msg.payload.puntos;
// .map crea un arreglo nuevo; x es la hora en milisegundos.
const puntos = (clave, nombre) => p.map(f => ({ x: new Date(f.timestamp).getTime(), y: f[clave], series: nombre }));
const serie = (clave, nombre) => ({ action: 'replace', payload: puntos(clave, nombre) });
return [
    // El primer gráfico muestra aire y producto: misma unidad, un solo eje.
    { action: 'replace', payload: puntos('tInt', 'Aire interior').concat(puntos('tProd', 'Producto')) },
    serie('tExt', 'T. exterior (°C)'),
    serie('hum', 'Humedad (%)'),
    serie('qFrig', 'Potencia frigorífica (kW)')
];

// Filas de la tabla de KPI a partir de la respuesta de /kpis.
if (!msg.payload || !msg.payload.kpis) return null;
msg.payload = msg.payload.kpis.map(k => ({ KPI: k.nombre, Valor: k.valor, Unidad: k.unidad, 'Fórmula': k.formula }));
return msg;

// Filas de la tabla de alarmas a partir de la respuesta de /alarms.
if (!msg.payload || !msg.payload.alarmas) return null;
const hora = iso => iso ? new Date(iso).toLocaleTimeString('es-EC') : '-';
msg.payload = msg.payload.alarmas.slice(0, 30).map(a => ({
    ID: a.id, Alarma: a.mensaje, Severidad: a.severidad, Activa: hora(a.horaActivacion),
    Normaliza: hora(a.horaNormalizacion), Estado: a.estado, Reconocida: a.reconocida ? hora(a.horaReconocimiento) : 'NO'
}));
return msg;

// Filas de la tabla de solicitudes a partir de la respuesta de /logs.
if (!msg.payload || !msg.payload.solicitudes) return null;
msg.payload = msg.payload.solicitudes.slice(0, 30).map(s => ({
    Hora: new Date(s.timestamp).toLocaleTimeString('es-EC'), 'Método': s.metodo, Comando: s.comando, 'Código': s.codigo, 'Tiempo (ms)': s.tiempo_ms
}));
return msg;

// Al pulsar una fila de la tabla se reconoce esa alarma por HTTP.
msg.url = 'http://127.0.0.1:1880/api/B10/alarms/' + msg.payload.ID + '/ack';
msg.payload = {};
return msg;

template:
/* Escena animada. Las animaciones dependen de clases en el contenedor .planta:
   comp-on, puerta-abierta, falla, fuera-rango. Las cajas las dibuja planta.js. */
.planta{width:100%;--p-tinta:#e6ebf0;--p-tenue:#9aa8b5;--p-linea:#4a5866;--p-frio:#7cc4f2;--p-calor:#f0a35e;--p-mal:#ff6b63}
.planta-svg{display:block;width:100%;height:auto}
.planta text{fill:var(--p-tinta);font-family:inherit}
.planta .p-etq{font-size:12px;letter-spacing:.09em;fill:var(--p-tenue)}
.planta .p-val{font-size:25px;font-weight:600;font-variant-numeric:tabular-nums}
.planta .p-grande{font-size:38px;font-weight:700;font-variant-numeric:tabular-nums}
.planta .p-mini{font-size:12px;fill:var(--p-tenue);font-variant-numeric:tabular-nums}
.planta .p-info{font-size:14px;fill:var(--p-tinta);font-variant-numeric:tabular-nums}
.planta .p-fuerte{fill:var(--p-tinta);font-weight:600}
.p-muro{fill:#3a4653;stroke:var(--p-linea);stroke-width:2}
.p-interior{fill:#17344a;transition:fill .8s}
.p-tarima{fill:#4d4032}
.p-caja{stroke:#10202c;stroke-width:1.5;transition:fill 1.5s}
.p-cinta{stroke:rgba(255,255,255,.35);stroke-width:2}
.p-caja-g.entra{animation:b10-entra 1.4s ease-out both}
.p-calor-prod path{fill:none;stroke:var(--p-calor);stroke-width:2.5;stroke-linecap:round;opacity:0;transition:opacity 1s}
.p-calor-prod.activo path{animation:b10-subir 2.2s ease-in-out infinite}
.p-calor-prod.activo path:nth-child(2){animation-delay:.7s}
.p-calor-prod.activo path:nth-child(3){animation-delay:1.4s}
.p-monta{opacity:0;transition:opacity .6s}
.p-monta.visible{opacity:1}
.p-monta.visible .p-monta-mov{animation:b10-monta 5s ease-in-out infinite}
.p-monta-cuerpo{fill:#d9a23a;stroke:#10202c;stroke-width:1.5}
.p-monta-cabina{fill:none;stroke:#d9a23a;stroke-width:3}
.p-monta-mastil,.p-monta-horq{fill:#55636f}
.p-monta-rueda{fill:#1c2630;stroke:#6b7885;stroke-width:2}
.p-monta-calor{fill:none;stroke:var(--p-calor);stroke-width:2.5;stroke-linecap:round;opacity:0;transition:opacity .8s}
.p-monta.visible .p-monta-calor{animation:b10-subir 1.8s ease-in-out infinite}
.p-caja-g.sale{animation:b10-sale 1.3s ease-in both}
.p-lampara rect{fill:#6a7682}
.p-luz{fill:#ffe6a3;opacity:.06;transition:opacity .8s}
.planta .p-carga-txt{fill:var(--p-calor)}
.p-evap{fill:#2b3743;stroke:var(--p-linea);stroke-width:1.5}
.p-eje{fill:#1c2630;stroke:var(--p-linea)}
.p-aspa{fill:var(--p-tenue)}
.p-tubo{fill:#101820;stroke:var(--p-linea)}
.p-rango{fill:rgba(124,196,242,.2)}
.p-nivel{fill:var(--p-frio);transition:y .8s,height .8s,fill .5s}
.p-sp{stroke:var(--p-tinta);stroke-width:2;transition:y1 .5s,y2 .5s}
.p-hueco{fill:#101820}
.p-puerta{transition:transform .9s ease-in-out}
.p-puerta rect{fill:#8796a5;stroke:#1c2630;stroke-width:2}
.p-puerta circle{fill:#1c2630}
.p-tubo-gas{fill:none;stroke:var(--p-linea);stroke-width:5}
.p-comp>rect{fill:#2b3743;stroke:var(--p-linea);stroke-width:2;transition:stroke .3s}
.p-led{fill:#55636f}
.p-aire,.p-frio,.p-falla{opacity:0;transition:opacity .4s}
.p-aire path{fill:none;stroke:var(--p-calor);stroke-width:3;stroke-dasharray:12 10}
.planta .p-falla{font-size:15px;font-weight:700;fill:var(--p-mal);letter-spacing:.1em}
.p-frio use{fill:var(--p-frio)}
/* Compresor encendido */
.comp-on .p-giro{animation:b10-giro .7s linear infinite}
.comp-on .p-frio{opacity:1}
.comp-on .p-frio use{animation:b10-caer 2.4s linear infinite}
.comp-on .p-frio use:nth-child(2){animation-delay:.7s}
.comp-on .p-frio use:nth-child(3){animation-delay:1.3s}
.comp-on .p-frio use:nth-child(4){animation-delay:.3s}
.comp-on .p-frio use:nth-child(5){animation-delay:1.9s}
.comp-on .p-frio use:nth-child(6){animation-delay:1s}
.comp-on .p-tubo-gas{stroke:var(--p-frio);stroke-dasharray:10 8;animation:b10-flujo .7s linear infinite}
.comp-on .p-led{fill:#5fd39a}
.comp-on .p-comp>rect{stroke:var(--p-frio)}
/* Puerta abierta */
.puerta-abierta .p-puerta{transform:translateY(-122px)}
.puerta-abierta .p-aire{opacity:1}
.puerta-abierta .p-aire path{animation:b10-aire .8s linear infinite}
/* Falla y fuera de rango */
.falla .p-falla{opacity:1;animation:b10-parpadeo 1s steps(2) infinite}
.falla .p-comp>rect{stroke:var(--p-mal);stroke-width:3}
.falla .p-led{fill:var(--p-mal)}
.fuera-rango .p-interior{fill:#4a3236}
.fuera-rango .p-nivel{fill:var(--p-mal)}
@keyframes b10-giro{to{transform:rotate(360deg)}}
@keyframes b10-caer{0%{transform:translateY(0);opacity:0}15%{opacity:1}85%{opacity:1}100%{transform:translateY(135px);opacity:0}}
@keyframes b10-flujo{to{stroke-dashoffset:-18}}
@keyframes b10-aire{to{stroke-dashoffset:-22}}
@keyframes b10-parpadeo{50%{opacity:.25}}
@keyframes b10-entra{0%{transform:translateX(-200px);opacity:0}25%{opacity:1}100%{transform:translateX(0)}}
@keyframes b10-subir{0%{transform:translateY(8px)}50%{transform:translateY(-6px)}100%{transform:translateY(8px)}}
@keyframes b10-monta{0%,100%{transform:translateX(0)}45%,55%{transform:translateX(14px)}}
@keyframes b10-sale{0%{transform:translateX(0);opacity:1}70%{opacity:1}100%{transform:translateX(-230px);opacity:0}}
@media (prefers-reduced-motion:reduce){.planta *{animation-duration:0s!important}}

/* Colores definidos en un solo lugar. Filosofía HMI: base neutra y color
   reservado para lo que requiere atención del operador. */
:root{
  --fondo:#141a21;--panel:#1d252e;--borde:#323e4a;--tinta:#e6ebf0;--tenue:#9aa8b5;
  --acento:#7cc4f2;--ok:#5fd39a;--aviso:#f2c14e;--mal:#ff6b63;
}
*{box-sizing:border-box}
body{margin:0;background:var(--fondo);color:var(--tinta);font:15px/1.45 "Segoe UI",system-ui,-apple-system,Roboto,sans-serif}
h1{font-size:20px;margin:0}
h2{font-size:13px;letter-spacing:.06em;text-transform:uppercase;color:var(--tenue);margin:0 0 10px;font-weight:600}
.cabecera{display:flex;flex-wrap:wrap;align-items:center;gap:12px 28px;padding:12px 20px;border-bottom:1px solid var(--borde);background:var(--panel)}
.cabecera p{margin:0;color:var(--tenue);font-size:13px}
.pestanas{display:flex;gap:4px}
.pestanas button{background:none;border:0;border-bottom:2px solid transparent;color:var(--tenue);font:inherit;font-weight:600;padding:7px 14px;cursor:pointer}
.pestanas button[aria-selected=true]{color:var(--tinta);border-color:var(--acento)}
.enlace{margin-left:auto;display:flex;align-items:center;gap:8px;font-size:13px;color:var(--tenue);font-variant-numeric:tabular-nums}
.punto{width:10px;height:10px;border-radius:50%;background:var(--mal)}
.enlace.ok .punto{background:var(--ok)}
.aviso-alarma{background:#4a2428;border-bottom:1px solid var(--mal);padding:9px 20px;font-weight:600}
.vista{display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:14px;padding:14px 20px;max-width:1320px;margin:auto}
.vista[hidden]{display:none}
#ingenieria{grid-template-columns:minmax(0,1fr) minmax(0,1fr)}
.panel{background:var(--panel);border:1px solid var(--borde);border-radius:8px;padding:14px;min-width:0}
.ancho{grid-column:1/-1}
.titulo-panel{display:flex;justify-content:space-between;align-items:center;margin-bottom:6px}
.titulo-panel h2{margin:0}
.modo{font-weight:700;font-size:13px;padding:3px 10px;border-radius:4px;background:#2b3743}
.modo.ENFRIANDO{color:var(--acento)}.modo.FALLA{color:var(--mal)}.modo.ESPERA{color:var(--aviso)}
.columna{display:flex;flex-direction:column;gap:14px;min-width:0}
.mandos{display:flex;flex-direction:column;gap:12px;align-self:start}
.bloque{display:flex;flex-direction:column;gap:8px}
.bloque h2{margin:0 0 2px}
.subbloque{display:flex;flex-direction:column;gap:6px;padding-top:8px;border-top:1px solid var(--borde)}
.subbloque label{font-size:13px;color:var(--tenue)}
.lista-alarmas{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:6px}
.lista-alarmas li{display:flex;justify-content:space-between;align-items:center;gap:8px;font-size:13px}
.sello{max-width:1320px;margin:6px auto 22px;padding:12px 20px;border-top:1px solid var(--borde);color:var(--tenue);font-size:12px;text-align:center;line-height:1.6}
.sello strong{color:var(--tinta)}
.bloque h2 label{cursor:inherit}
.fila{display:flex;gap:8px;align-items:flex-end}
.fila>*{flex:1;min-width:0}
.nota{margin:0;font-size:13px;color:var(--tenue)}
.campo{display:flex;flex-direction:column;gap:4px;font-size:12px;color:var(--tenue)}
input[type=range]{accent-color:var(--acento);padding:0;border:0;background:none;height:34px}
output{flex:0 0 64px;text-align:right;font-weight:700;font-variant-numeric:tabular-nums}
.btn{font:inherit;font-weight:600;color:#10202c;background:var(--acento);border:0;border-radius:6px;padding:10px 12px;cursor:pointer}
.btn:hover{filter:brightness(1.1)}
.btn:focus-visible,select:focus-visible,input:focus-visible,.pestanas button:focus-visible{outline:2px solid var(--tinta);outline-offset:2px}
.btn.secundario{background:#2b3743;color:var(--tinta);border:1px solid var(--borde)}
.btn.activo{background:#4a2428;color:#ffd7d4;border:1px solid var(--mal)}
input,select{font:inherit;color:var(--tinta);background:#141a21;border:1px solid var(--borde);border-radius:6px;padding:8px;min-width:0}
input{flex:1;width:100%}
.selector{font-size:13px;color:var(--tenue)}
.fila-datos{display:grid;gap:14px;grid-template-columns:repeat(3,minmax(0,1fr))}
.fila-kpi{grid-column:1/-1;display:grid;gap:14px;grid-template-columns:repeat(5,minmax(0,1fr))}
