.graficos{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}
.grafico{position:relative;min-width:0}
.grafico h3{margin:0 0 2px;font-size:14px;font-weight:600}
.grafico svg{display:block;width:100%;height:190px;touch-action:none}
.grafico .rejilla{stroke:var(--borde);stroke-width:1}
.grafico .eje{fill:var(--tenue);font-size:11px}
.grafico .serie{fill:none;stroke:var(--acento);stroke-width:2;stroke-linejoin:round}
