.leyenda{font-size:12px;color:var(--tenue);font-weight:400;margin-left:8px}
.leyenda i{display:inline-block;width:14px;height:3px;border-radius:2px;vertical-align:middle;margin:0 4px 0 8px}
.grafico .banda{fill:rgba(124,196,242,.12)}
.grafico .guia{stroke:var(--tinta);stroke-dasharray:4 4;stroke-width:1}
.grafico .cursor{stroke:var(--tenue)}
.grafico .marca{fill:var(--acento);stroke:var(--panel);stroke-width:2}
.tip{position:absolute;pointer-events:none;background:#0d1319;border:1px solid var(--borde);border-radius:4px;padding:3px 7px;font-size:12px;white-space:nowrap;font-variant-numeric:tabular-nums}
.tabla-scroll{max-height:280px;overflow:auto}
