th,td{padding:6px 8px;border-bottom:1px solid var(--borde)}
td.vacio{color:var(--tenue);text-align:center;padding:16px}
.sev{font-weight:700}.sev.CRITICA{color:var(--mal)}.sev.ALTA{color:#ff9a62}.sev.MEDIA{color:var(--aviso)}
