.mini{font:inherit;font-size:12px;font-weight:600;background:#2b3743;color:var(--tinta);border:1px solid var(--borde);border-radius:4px;padding:3px 8px;cursor:pointer}
.botones-error{display:flex;flex-direction:column;gap:8px}
.toast{position:fixed;right:18px;bottom:18px;max-width:380px;background:#0d1319;border:1px solid var(--borde);border-left:4px solid var(--ok);border-radius:6px;padding:10px 14px;font-size:14px}
