// =====================================================================
// app.js - Dashboard HTML de la cámara frigorífica B10.
// Este archivo NO usa variables de Node-RED: todo llega con fetch() a la API.
// =====================================================================

const API = '/api/B10';      // misma dirección desde la que Node-RED entrega esta página
const POLLING_MS = 1500;     // intervalo declarado de consulta rápida
const POLLING_LENTO_MS = 4000; // históricos, KPI y tablas
const TIMEOUT_MS = 3000;     // si la API tarda más, se cancela la solicitud

let ultimoEstado = null;     // último JSON de /status
let ultimaTelemetria = null; // último JSON de /telemetry

// Dibuja el estado recibido por HTTP sobre la escena SVG.
// raiz: contenedor .planta | tel: JSON de /telemetry | est: JSON de /status
function actualizarPlanta(raiz, tel, est) {
    const v = tel.variables;
    const tInt = v.temperaturaInterior.valor;
    const tProd = tel.producto.temperatura.valor;
    const [tMin, tMax] = est.rangoAceptable_C;
    const coma = (n, d) => n.toFixed(d).replace('.', ',');   // formato decimal local
    const NS = 'http://www.w3.org/2000/svg';                 // los elementos SVG necesitan su espacio de nombres

    // classList.toggle(nombre, condicion) pone o quita la clase; el CSS anima.
    raiz.classList.toggle('comp-on', est.compresorEncendido);
    raiz.classList.toggle('puerta-abierta', est.puertaAbierta);
    raiz.classList.toggle('falla', est.fallaCompresor);
    raiz.classList.toggle('fuera-rango', tInt < tMin || tInt > tMax);

    // Textos: cada elemento con data-b indica qué dato muestra.
    const textos = {
        tInt: coma(tInt, 1) + ' °C',
        tExt: coma(v.temperaturaExterior.valor, 1) + ' °C',
        hum: 'Humedad ' + coma(v.humedad.valor, 0) + ' %',
        q: coma(v.potenciaFrigorifica.valor, 2) + ' kW',
        comp: est.compresorEncendido ? 'Encendido' : (est.fallaCompresor ? 'En falla' : 'Apagado'),
        puerta: est.puertaAbierta ? 'Puerta abierta' : 'Puerta cerrada',
        producto: est.cajas ? 'Producto: ' + est.cajas + ' cajas a ' + coma(tProd, 1) + ' °C' : 'Cámara vacía',
        carga: est.cargaExtra_kW > 0 ? 'Carga adicional: ' + coma(est.cargaExtra_kW, 1) + ' kW' : '',
        velocidad: 'Velocidad x' + est.escalaTiempo
    };
    raiz.querySelectorAll('[data-b]').forEach(el => { el.textContent = textos[el.dataset.b]; });

    // Cajas: 3 filas de 8. Se llenan desde el fondo (derecha) hacia la puerta.
    const grupo = raiz.querySelector('[data-cajas]');
    const primeraVez = grupo.dataset.n === undefined;          // al abrir la página no se anima
    const antes = Number(grupo.dataset.n || 0);
    if (antes !== est.cajas) {
        // Cajas que todavía están dentro (las que van saliendo ya no cuentan).
        const dentro = Array.from(grupo.querySelectorAll('.p-caja-g:not(.sale)'));
        // Salen cajas: las más cercanas a la puerta se deslizan hacia afuera y luego se borran.
        for (let i = dentro.length - 1, orden = 0; i >= est.cajas; i--, orden++) {
            const g = dentro[i];
            g.classList.remove('entra');
            g.classList.add('sale');
            g.style.animationDelay = (orden * 0.12) + 's';
            setTimeout(() => g.remove(), 1400 + orden * 120);   // setTimeout espera a que termine la animación
        }
        for (let i = dentro.length; i < est.cajas; i++) {      // entran cajas
            const col = 7 - (i % 8), fila = Math.floor(i / 8);
            const g = document.createElementNS(NS, 'g');
            g.setAttribute('class', 'p-caja-g' + (primeraVez ? '' : ' entra'));
            g.style.animationDelay = ((i - dentro.length) * 0.12) + 's';         // una detrás de otra
            g.innerHTML = `<rect class="p-caja" x="${252 + col * 34}" y="${280 - fila * 27}" width="31" height="26" rx="2"/>` +
                          `<line class="p-cinta" x1="${267.5 + col * 34}" x2="${267.5 + col * 34}" y1="${281 - fila * 27}" y2="${305 - fila * 27}"/>`;
            grupo.appendChild(g);
        }
        grupo.dataset.n = est.cajas;
    }
    // Color según la temperatura del producto: azul (frío, ≤ 4 °C), cartón (12 °C)
    // y naranja (caliente, ≥ 25 °C). Se mezclan los canales rojo, verde y azul.
    const paradas = [[4, [74, 134, 184]], [12, [156, 138, 110]], [25, [212, 105, 47]]];
    const mezcla = t => {
        if (t <= paradas[0][0]) return paradas[0][1];
        for (let i = 1; i < paradas.length; i++) {
            const [t0, c0] = paradas[i - 1], [t1, c1] = paradas[i];
            if (t <= t1) return c0.map((c, k) => Math.round(c + (c1[k] - c) * (t - t0) / (t1 - t0)));
        }
        return paradas[paradas.length - 1][1];
    };
    const color = 'rgb(' + mezcla(tProd).join(',') + ')';
    grupo.querySelectorAll('.p-caja').forEach(c => { c.style.fill = color; });

    // Ondas de calor sobre las cajas cuando el producto está más caliente que el aire.
    const calor = raiz.querySelector('[data-calor]');
    const intensidad = est.cajas ? Math.min(1, Math.max(0, (tProd - tInt - 1) / 8)) : 0;
    calor.classList.toggle('activo', intensidad > 0);
    calor.querySelectorAll('path').forEach(p => { p.style.opacity = intensidad; });

    // Montacargas visible con carga adicional; su calor crece con los kW. La lámpara también.
    const fraccion = Math.min(1, est.cargaExtra_kW / est.cargaExtraMax_kW);
    const monta = raiz.querySelector('[data-monta]');
    monta.classList.toggle('visible', est.cargaExtra_kW > 0);
    monta.querySelectorAll('.p-monta-calor').forEach(p => { p.style.opacity = 0.3 + fraccion * 0.7; });
    raiz.querySelector('.p-luz').style.opacity = 0.06 + fraccion * 0.3;

    // Termómetro: 200 px representan de 0 a 12 °C.
    const px = t => 200 - Math.min(12, Math.max(0, t)) / 12 * 200;
    const nivel = raiz.querySelector('[data-nivel]');
    nivel.setAttribute('y', px(tInt));
    nivel.setAttribute('height', 200 - px(tInt));
    const sp = raiz.querySelector('[data-sp]');
    sp.setAttribute('y1', px(est.consigna_C));
    sp.setAttribute('y2', px(est.consigna_C));
}

// Atajo para buscar elementos por id.
const $ = id => document.getElementById(id);
const coma = (n, d) => Number(n).toFixed(d).replace('.', ',');
const hora = iso => iso ? new Date(iso).toLocaleTimeString('es-EC') : '-';

// ---------------------------------------------------------------------
// Cliente HTTP con tiempo límite.
// AbortController permite cancelar el fetch cuando vence el timeout.
// ---------------------------------------------------------------------
async function http(ruta, opciones = {}) {
    const control = new AbortController();
    const temporizador = setTimeout(() => control.abort(), TIMEOUT_MS);
    const inicio = performance.now();                 // reloj de alta precisión
    try {
        const r = await fetch(API + ruta, { ...opciones, signal: control.signal, cache: 'no-store' });
        const cuerpo = await r.json();                // convierte la respuesta a objeto
        return { ok: r.ok, codigo: r.status, cuerpo, ms: Math.round(performance.now() - inicio) };
    } catch (error) {
        // AbortError = timeout; cualquier otro caso = sin conexión.
        const tipo = error.name === 'AbortError' ? 'TIMEOUT' : 'SIN_CONEXION';
        return { ok: false, codigo: 0, cuerpo: { error: { codigo: tipo, mensaje: tipo === 'TIMEOUT' ? 'La API no respondió en ' + TIMEOUT_MS + ' ms' : 'No se pudo conectar con la API' } }, ms: 0 };
    } finally {
        clearTimeout(temporizador);                   // siempre limpia el temporizador
    }
}

// Envía JSON y muestra el resultado en pantalla.
async function enviar(metodo, ruta, cuerpo) {
    const r = await http(ruta, {
        method: metodo,
        headers: { 'Content-Type': 'application/json' },
        body: cuerpo ? JSON.stringify(cuerpo) : undefined   // JSON.stringify pasa de objeto a texto
    });
    aviso(r.ok ? metodo + ' ' + r.codigo + ' · ' + r.ms + ' ms · ' + (r.cuerpo.resultado || 'OK')
               : 'Error ' + r.codigo + ' · ' + r.cuerpo.error.mensaje, !r.ok);
    consultarRapido();
    consultarLento();
    return r;
}
const comando = (command, params) => enviar('POST', '/commands', { command, params });

function aviso(texto, esError) {
    const t = $('toast');
    t.textContent = texto;
    t.classList.toggle('error', !!esError);
    t.hidden = false;
    clearTimeout(aviso.t);
    aviso.t = setTimeout(() => { t.hidden = true; }, 4000);
}

// ---------------------------------------------------------------------
// Polling rápido: telemetría y estado para la animación.
// ---------------------------------------------------------------------
async function consultarRapido() {
    // Promise.all espera las dos respuestas a la vez.
    const [tel, est] = await Promise.all([http('/telemetry'), http('/status')]);
    const enlace = $('enlace');
    if (!tel.ok || !est.ok) {
        enlace.classList.remove('ok');
        $('enlaceTexto').textContent = (tel.cuerpo.error || est.cuerpo.error || {}).codigo || 'Error';
        return;
    }
    enlace.classList.add('ok');
    $('enlaceTexto').textContent = 'HTTP ' + tel.codigo + ' · ' + tel.ms + ' ms · cada ' + coma(POLLING_MS / 1000, 1) + ' s';
    ultimaTelemetria = tel.cuerpo;
    ultimoEstado = est.cuerpo;
    pintarOperacion(tel.cuerpo, est.cuerpo);
    pintarBalance(tel.cuerpo);
}

function pintarOperacion(tel, est) {
    actualizarPlanta($('planta'), tel, est);

    const dias = Math.floor(tel.simTime_s / 86400);
    const h = new Date(tel.simTime_s * 1000).toISOString().slice(11, 16);
    $('dispositivo').textContent = tel.deviceId + ' · reloj simulado ' + (dias ? dias + ' d ' : '') + h + ' · 1 s real = ' + est.escalaTiempo + ' s';

    const modo = $('modo');
    modo.textContent = est.modo;
    modo.className = 'modo ' + est.modo;

    const v = tel.variables;
    const tiles = [
        ['Temperatura interior', v.temperaturaInterior, 1, 'Consigna ' + coma(est.consigna_C, 1) + ' ± ' + coma(est.histeresis_C, 1) + ' °C'],
        ['Temperatura exterior', v.temperaturaExterior, 1, 'Perturbación ambiental'],
        ['Humedad', v.humedad, 0, est.puertaAbierta ? 'Sube por la puerta abierta' : 'Interior de la cámara'],
        ['Potencia frigorífica', v.potenciaFrigorifica, 2, 'Eléctrica ' + coma(tel.potenciaElectrica.valor, 2) + ' kW'],
        ['Temperatura del producto', tel.producto.temperatura, 1, est.cajas + ' de ' + est.capacidadCajas + ' cajas'],
        ['Carga térmica total', tel.cargaTermicaTotal, 2, 'Calor que entra en este momento']
    ];
    $('datos').innerHTML = tiles.map(([n, x, d, nota]) =>
        `<div class="dato"><span>${n}</span><b>${coma(x.valor, d)}</b><small>${x.unidad}</small><em>${nota}</em></div>`).join('');

    // Las etiquetas de los botones dicen la acción que sucederá.
    const refrig = $('btnRefrig'), puerta = $('btnPuerta'), falla = $('btnFalla');
    refrig.textContent = est.refrigeracionActiva ? 'Apagar refrigeración' : 'Activar refrigeración';
    puerta.textContent = est.puertaAbierta ? 'Cerrar puerta' : 'Abrir puerta';
    falla.textContent = est.fallaCompresor ? 'Reparar compresor' : 'Provocar falla del compresor';
    falla.classList.toggle('activo', est.fallaCompresor);

    // Los campos se sincronizan con el estado real, salvo mientras el usuario los edita.
    if (document.activeElement !== $('consigna')) $('consigna').value = est.consigna_C;
    if (document.activeElement !== $('carga')) { $('carga').value = est.cargaExtra_kW; $('cargaValor').textContent = coma(est.cargaExtra_kW, 1) + ' kW'; }
    if (document.activeElement !== $('velocidad')) $('velocidad').value = est.escalaTiempo;
    $('productoNota').textContent = est.cajas + ' de ' + est.capacidadCajas + ' cajas a ' + coma(est.temperaturaProducto_C, 1) + ' °C. ' +
        (est.puertaAbierta ? 'Puerta abierta: puede ingresar o retirar.' : 'Abra la puerta para ingresar o retirar.');
}

function pintarBalance(tel) {
    const b = tel.balance_kW;
    if (!b) return;
    const filas = [['Paredes', b.qParedes], ['Puerta', b.qPuerta], ['Luces y carga adicional', b.qInterna], ['Producto (cajas)', b.qProducto], ['Ganancia total', b.qGanancias], ['Extracción del compresor', b.qFrig], ['Neto (+ calienta)', b.qGanancias - b.qFrig]];
    $('tablaBalance').innerHTML = '<tr><th>Término</th><th>kW</th></tr>' + filas.map(([n, x]) => `<tr><td>${n}</td><td>${coma(x, 2)}</td></tr>`).join('');
}

// ---------------------------------------------------------------------
// Polling lento: KPI, históricos, alarmas y registro de solicitudes.
// ---------------------------------------------------------------------
async function consultarLento() {
    const ventana = $('ventana').value;
    const [kpi, his, alm, log] = await Promise.all([
        http('/kpis'),
        http('/history?ventana_min=' + ventana + '&variables=tInt,tProd,tExt,hum,qFrig'),
        http('/alarms'),
        http('/logs')
    ]);
    if (kpi.ok) pintarKpis(kpi.cuerpo);
    if (his.ok) pintarHistoricos(his.cuerpo);
    if (alm.ok) pintarAlarmas(alm.cuerpo.alarmas);
    if (log.ok) pintarLog(log.cuerpo.solicitudes);
}

function pintarKpis(d) {
    $('kpis').innerHTML = d.kpis.map(k => {
        const nota = k.id === 'recuperacion' ? (k.enExcursion ? 'Fuera de rango ahora' : 'Promedio ' + coma(k.promedio_min, 1) + ' min') : k.formula;
        const decimales = k.unidad === 'n' ? 0 : (k.unidad === 'kWh' ? 3 : 1);
        return `<div class="dato"><span>${k.nombre}</span><b>${coma(k.valor, decimales)}</b><small>${k.unidad}</small><em>${nota}</em></div>`;
    }).join('');
}

function pintarAlarmas(lista) {
    const activas = lista.filter(a => a.estado === 'ACTIVA');
    const banner = $('avisoAlarma');
    banner.hidden = activas.length === 0;
    banner.textContent = activas.map(a => '▲ ' + a.severidad + ': ' + a.mensaje).join('   ');

    // Lista corta en la vista de operación, con botón de reconocer.
    $('alarmasActivas').innerHTML = activas.length
        ? activas.map(a => `<li><span><b class="sev ${a.severidad}">${a.severidad}</b> ${a.mensaje}</span>${a.reconocida ? '<span class="nota">Reconocida</span>' : `<button class="mini" data-ack="${a.id}">Reconocer</button>`}</li>`).join('')
        : '<li class="nota">Sin alarmas activas</li>';

    const t = $('tablaAlarmas');
    if (!lista.length) { t.innerHTML = '<tr><td class="vacio">Sin alarmas registradas</td></tr>'; return; }
    t.innerHTML = '<tr><th>ID</th><th>Alarma</th><th>Severidad</th><th>Condición</th><th>Activó</th><th>Normalizó</th><th>Estado</th><th>Reconocimiento</th></tr>' +
        lista.slice(0, 50).map(a => `<tr><td>${a.id}</td><td>${a.mensaje}</td><td class="sev ${a.severidad}">${a.severidad}</td><td>${a.condicion}</td><td>${hora(a.horaActivacion)}</td><td>${hora(a.horaNormalizacion)}</td><td>${a.estado}</td><td>${a.reconocida ? hora(a.horaReconocimiento) : `<button class="mini" data-ack="${a.id}">Reconocer</button>`}</td></tr>`).join('');
}

function pintarLog(lista) {
    const t = $('tablaLog');
    if (!lista.length) { t.innerHTML = '<tr><td class="vacio">Aún no hay solicitudes de control</td></tr>'; return; }
    t.innerHTML = '<tr><th>Hora</th><th>Método</th><th>Ruta</th><th>Comando</th><th>Código</th><th>Tiempo</th></tr>' +
        lista.slice(0, 50).map(s => `<tr><td>${hora(s.timestamp)}</td><td>${s.metodo}</td><td>${s.ruta}</td><td>${s.comando}</td><td class="cod${String(s.codigo)[0]}">${s.codigo}</td><td>${s.tiempo_ms} ms</td></tr>`).join('');
}

// ---------------------------------------------------------------------
// Gráficos SVG propios: un gráfico por variable, un solo eje en cada uno.
// ---------------------------------------------------------------------
const SERIES = [
    { clave: 'tInt', titulo: 'Temperatura del aire y del producto', unidad: '°C', dec: 2, extra: 'tProd' },
    { clave: 'tExt', titulo: 'Temperatura exterior', unidad: '°C', dec: 2 },
    { clave: 'hum', titulo: 'Humedad', unidad: '%', dec: 1 },
    { clave: 'qFrig', titulo: 'Potencia frigorífica', unidad: 'kW', dec: 2 }
];
const NS = 'http://www.w3.org/2000/svg';

function crearGraficos() {
    SERIES.forEach(s => {
        const caja = document.createElement('div');
        caja.className = 'grafico';
        const leyenda = s.extra ? '<span class="leyenda"><i style="background:#7cc4f2"></i>aire<i style="background:#f0a35e"></i>producto</span>' : '';
        caja.innerHTML = `<h3>${s.titulo} (${s.unidad})${leyenda}</h3><svg id="g-${s.clave}" viewBox="0 0 560 190" preserveAspectRatio="none"></svg><div class="tip" hidden></div>`;
        $('graficos').appendChild(caja);
    });
}

function pintarHistoricos(d) {
    SERIES.forEach(s => dibujar(s, d.puntos));
}

function dibujar(s, puntos) {
    const svg = $('g-' + s.clave);
    const W = 560, H = 190, izq = 38, der = 8, arr = 8, aba = 22;
    if (puntos.length < 2) { svg.innerHTML = `<text class="eje" x="${izq}" y="90">Acumulando datos…</text>`; return; }

    const valores = puntos.map(p => p[s.clave]).concat(s.extra ? puntos.map(p => p[s.extra]) : []);
    let min = Math.min(...valores), max = Math.max(...valores);
    const est = ultimoEstado;
    if (s.clave === 'tInt' && est) {           // muestra siempre el rango aceptable
        min = Math.min(min, est.rangoAceptable_C[0] - 1);
        max = Math.max(max, est.rangoAceptable_C[1] + 1);
    }
    if (s.clave === 'qFrig') { min = 0; max = Math.max(max, 5.5); }
    if (max - min < 1) { const c = (max + min) / 2; min = c - .5; max = c + .5; }

    const t0 = puntos[0].simTime_s, t1 = puntos[puntos.length - 1].simTime_s;
    const x = t => izq + (t - t0) / (t1 - t0 || 1) * (W - izq - der);   // tiempo -> píxel
    const y = v => arr + (max - v) / (max - min) * (H - arr - aba);     // valor -> píxel

    let html = '';
    for (let i = 0; i <= 3; i++) {             // rejilla discreta
        const v = min + (max - min) * i / 3;
        html += `<line class="rejilla" x1="${izq}" x2="${W - der}" y1="${y(v)}" y2="${y(v)}"/><text class="eje" x="${izq - 5}" y="${y(v) + 4}" text-anchor="end">${coma(v, 1)}</text>`;
    }
    if (s.clave === 'tInt' && est) {           // banda 2-6 °C y consigna
        const [a, b] = est.rangoAceptable_C;
        html += `<rect class="banda" x="${izq}" width="${W - izq - der}" y="${y(b)}" height="${y(a) - y(b)}"/><line class="guia" x1="${izq}" x2="${W - der}" y1="${y(est.consigna_C)}" y2="${y(est.consigna_C)}"/>`;
    }
    html += `<text class="eje" x="${izq}" y="${H - 5}">${hora(puntos[0].timestamp)}</text><text class="eje" x="${W - der}" y="${H - 5}" text-anchor="end">${hora(puntos[puntos.length - 1].timestamp)}</text>`;
    html += `<polyline class="serie" vector-effect="non-scaling-stroke" points="${puntos.map(p => x(p.simTime_s).toFixed(1) + ',' + y(p[s.clave]).toFixed(1)).join(' ')}"/>`;
    if (s.extra) html += `<polyline class="serie extra" vector-effect="non-scaling-stroke" points="${puntos.map(p => x(p.simTime_s).toFixed(1) + ',' + y(p[s.extra]).toFixed(1)).join(' ')}"/>`;
    html += `<line class="cursor" y1="${arr}" y2="${H - aba}" visibility="hidden"/><circle class="marca" r="4" visibility="hidden"/>`;
    svg.innerHTML = html;

    // Cursor con lectura exacta del punto más cercano.
    const cursor = svg.querySelector('.cursor'), marca = svg.querySelector('.marca'), tip = svg.parentElement.querySelector('.tip');
    svg.onpointermove = ev => {
        const caja = svg.getBoundingClientRect();
        const px = (ev.clientX - caja.left) / caja.width * W;
        const i = Math.max(0, Math.min(puntos.length - 1, Math.round((px - izq) / (W - izq - der) * (puntos.length - 1))));
        const p = puntos[i], X = x(p.simTime_s), Y = y(p[s.clave]);
        cursor.setAttribute('x1', X); cursor.setAttribute('x2', X); cursor.setAttribute('visibility', 'visible');
        marca.setAttribute('cx', X); marca.setAttribute('cy', Y); marca.setAttribute('visibility', 'visible');
        tip.hidden = false;
        tip.textContent = hora(p.timestamp) + ' · ' + coma(p[s.clave], s.dec) + ' ' + s.unidad + (s.extra ? ' · producto ' + coma(p[s.extra], s.dec) + ' ' + s.unidad : '');
        tip.style.left = Math.min(X / W * caja.width + 8, caja.width - 130) + 'px';
        tip.style.top = '26px';
    };
    svg.onpointerleave = () => { cursor.setAttribute('visibility', 'hidden'); marca.setAttribute('visibility', 'hidden'); tip.hidden = true; };
}

