$('btnPuerta').onclick = () => comando(ultimoEstado.puertaAbierta ? 'CERRAR_PUERTA' : 'ABRIR_PUERTA');
$('btnFalla').onclick = () => comando(ultimoEstado.fallaCompresor ? 'REPARAR_COMPRESOR' : 'FALLAR_COMPRESOR');
$('btnReiniciar').onclick = () => comando('REINICIAR');
$('btnReiniciarKpi').onclick = () => comando('REINICIAR_KPI');

